CREATE OR REPLACE FUNCTION private.dic_promote_pending_coffee(sid uuid, method text, evidence jsonb DEFAULT '{}'::jsonb, distinct_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 s public.coffee_submissions; new_c public.coffees; cid uuid; locked_key text;
 raw jsonb; roaster_text text; known_name text; brandkey text; official_host text; host text;
 product_name text; source_title text; namekey text; existed uuid; same_url uuid;
 existing_count integer; same_url_count integer; declared_release text; official_release text; conflicting boolean;
 info jsonb; source_kind text;
begin
 if method not in ('admin_approved','official_verified','admin_reviewed','member_auto_approved') then
  raise exception using errcode='22023',message='Unsupported verification method.';
 end if;
 if method='official_verified'
   and (current_setting('role',true) is distinct from 'service_role'
     or coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
             nullif(current_setting('request.jwt.claim.role',true),'')) is distinct from 'service_role') then
  raise exception using errcode='42501',message='Only the trusted source verifier may approve external evidence.';
 end if;
 if jsonb_typeof(evidence) is distinct from 'object' or octet_length(evidence::text)>10000 then
  raise exception using errcode='22023',message='Invalid evidence payload.';
 end if;
 select * into s from public.coffee_submissions where id=sid for update;
 if not found then raise exception using errcode='22023',message='Coffee submission unavailable.';end if;
 if method='official_verified' then
  perform 1 from private.beta_members where owner_id=s.owner_id and enabled for share;
  if not found then
   raise exception using errcode='42501',message='Admitted submission owner required for official verification.';
  end if;
 end if;
 if method='admin_reviewed' and
    ((select auth.uid()) is null or not private.is_admin()) then
  raise exception using errcode='42501',message='Only an administrator may review a member coffee.';
 end if;
 if method='member_auto_approved' and
    ((select auth.uid()) is null or not private.is_member() or auth.uid() is distinct from s.owner_id) then
  raise exception using errcode='42501',message='Admitted submission owner required for automatic approval.';
 end if;
 if method='admin_approved' and
    (not private.is_admin() or auth.uid() is distinct from s.owner_id) then
  raise exception using errcode='42501',message='Only the owning administrator can automatically approve their submissions.';
 end if;
 if s.status in ('approved','merged') and s.canonical_coffee_id is not null then
  return jsonb_build_object('ok',true,'coffee_id',s.canonical_coffee_id,'status','verified','already_verified',true);
 end if;
 if method='official_verified' and evidence->>'submission_revision' is distinct from s.revision::text then
  raise exception using errcode='40001',message='Submission changed before source verification; refresh and retry.';
 end if;
 if s.status not in ('pending','conflict') then
  raise exception using errcode='23514',message='Submission cannot be verified from this state.';
 end if;
 raw:=s.proposed_data;
 brandkey:=private.dic_canonical_roaster_key(raw->>'roaster');
 namekey:=private.dic_coffee_key(raw->>'name');
 if namekey is null or brandkey is null then
  raise exception using errcode='22023',message='Coffee and roaster names must be provided.';
 end if;
 select proof->>'canonical_name',proof->>'official_domain'
 into known_name,official_host
 from (select private.dic_verified_roaster_page_proof(raw->>'roaster') as proof) p;
 roaster_text:=coalesce(known_name,btrim(raw->>'roaster'));
 declared_release:=nullif(btrim(raw->>'release_label'),'');
 if method='official_verified' then
  if official_host is null or nullif(s.source_url,'') is null or
    evidence->>'evidence_kind' not in ('jsonld_product','official_product_page') then
   raise exception using errcode='23514',message='Verified roaster product evidence is required.';
  end if;
  if s.source_url !~ '^https://' then
   raise exception using errcode='23514',message='The official product URL must use HTTPS.';
  end if;
  host:=lower(split_part(split_part(regexp_replace(s.source_url,'^https://',''),'/',1),'?',1));
  if host not in (official_host,'www.'||official_host) then
   raise exception using errcode='23514',message='Source URL does not belong to the verified roaster.';
  end if;
  if private.dic_source_key(s.source_url) is distinct from private.dic_source_key(evidence->>'checked_url') then
   raise exception using errcode='23514',message='Source evidence does not match the submitted product URL.';
  end if;
  product_name:=nullif(btrim(evidence->>'product_name'),'');
  if product_name is null or coalesce(length(product_name),0)>250 then
   raise exception using errcode='23514',message='No trustworthy product title was extracted.';
  end if;
  -- Worker must prove recognizable whole-name identity, not substring Wuri/Wurist.
  if coalesce((evidence->>'title_matches')::boolean,false) is not true then
   raise exception using errcode='23514',message='Product title did not independently match the entered coffee name.';
  end if;
  official_release:=nullif(btrim(evidence->>'release_label'),'');
  if declared_release is not null and official_release is not null
     and private.dic_coffee_key(declared_release) is distinct from private.dic_coffee_key(official_release) then
   raise exception using errcode='23514',message='Release labels conflict.';
  end if;
  if coalesce((evidence->>'contradictory_facts')::boolean,false) then
   raise exception using errcode='23514',message='Source fact conflict requires human review.';
  end if;
 end if;
 -- Protect against two users simultaneously submitting the same product.
 locked_key:=brandkey||':'||namekey;
 perform pg_advisory_xact_lock(hashtextextended(locked_key,9460));
 select count(*),min(c.id::text)::uuid into same_url_count,same_url from public.coffees c
 where c.verification_state='verified' and c.merged_into_id is null
  and private.dic_canonical_roaster_key(c.roaster)=brandkey
  and private.dic_coffee_key(c.name)=namekey
  -- Recycled product URLs cannot silently collapse separate unknown harvests.
  and declared_release is not null
  and private.dic_coffee_key(c.release_label)=private.dic_coffee_key(declared_release)
  and (nullif(btrim(raw->>'origin'),'') is null or c.origin is null
       or private.dic_coffee_key(c.origin)=private.dic_coffee_key(raw->>'origin'))
  and (nullif(btrim(raw->>'process'),'') is null or c.process is null
       or private.dic_coffee_key(c.process)=private.dic_coffee_key(raw->>'process'))
  and s.source_url is not null
  and exists(select 1 from public.coffee_sources src where src.coffee_id=c.id
    and src.source_kind='roaster_page'
    and private.dic_source_key(src.source_url)=private.dic_source_key(s.source_url))
;
 if same_url_count=1 and same_url is not null then
  return private.dic_link_pending_coffee(sid,same_url,'canonical_reused',
   jsonb_build_object('method',method,'source',coalesce(evidence->>'checked_url',s.source_url)));
 end if;
 select count(*) into existing_count from public.coffees c
 where c.verification_state='verified' and c.merged_into_id is null
   and private.dic_canonical_roaster_key(c.roaster)=brandkey
   and (
     private.dic_coffee_key(c.name)=namekey
     or extensions.similarity(private.dic_coffee_key(c.name),namekey)>=0.63
   )
   and (private.dic_coffee_key(c.release_label) is null
     or private.dic_coffee_key(declared_release) is null
     or private.dic_coffee_key(c.release_label)=private.dic_coffee_key(declared_release));
 if existing_count>0 and (method in ('official_verified','member_auto_approved') or not distinct_confirmed) then
  insert into private.dic_coffee_audit(submission_id,actor_id,event_kind,evidence)
    values(sid,auth.uid(),'needs_review',
      jsonb_build_object('reason','potential_existing_release','method',method));
  return jsonb_build_object('ok',false,'code','needs_confirmation','status','pending');
 end if;

 -- A later member cannot leapfrog an unresolved older same-identity Pending
 -- submission and manufacture another canonical ID. Keep the older entry
 -- for the ordinary signed-in retry path; never disclose its private owner.
 if method='member_auto_approved' and exists (
  select 1 from public.coffee_submissions prev
  where prev.id<>s.id and prev.canonical_coffee_id is null
    and prev.status in ('pending','conflict')
    and (prev.created_at,prev.id)<(s.created_at,s.id)
    and private.dic_canonical_roaster_key(prev.proposed_data->>'roaster')=brandkey
    and (private.dic_coffee_key(prev.proposed_data->>'name')=namekey
      or extensions.similarity(private.dic_coffee_key(prev.proposed_data->>'name'),namekey)>=0.63)
    and (nullif(btrim(prev.proposed_data->>'release_label'),'') is null
      or declared_release is null
      or private.dic_coffee_key(prev.proposed_data->>'release_label')
        =private.dic_coffee_key(declared_release))
 ) then
  insert into private.dic_coffee_audit(submission_id,actor_id,event_kind,evidence)
  values(sid,auth.uid(),'needs_review',
   jsonb_build_object('reason','older_unresolved_pending_identity','method',method));
  return jsonb_build_object('ok',false,'code','needs_confirmation','status','pending');
 end if;
 insert into public.coffees(name,roaster,release_label,origin,elevation_m,roast_level,process,variety,
                            producer,tasting_notes,summary,espresso_notes,roaster_recipe,
                            verification_state,created_at)
 values(btrim(raw->>'name'),roaster_text,declared_release,nullif(btrim(raw->>'origin'),''),
   nullif(btrim(raw->>'elevation_m'),''),
   case when raw->>'roast_level'='Light-Medium' then 'Medium-Light'
    when raw->>'roast_level' in ('Ultra Light','Very Light','Light','Medium-Light','Medium','Medium-Dark','Dark') then raw->>'roast_level'
    else null end,
   nullif(btrim(raw->>'process'),''),nullif(btrim(raw->>'variety'),''),nullif(btrim(raw->>'producer'),''),
   nullif(btrim(raw->>'tasting_notes'),''),nullif(btrim(raw->>'summary'),''),nullif(btrim(raw->>'espressoNotes'),''),
   case when jsonb_typeof(raw->'roaster_recipe')='object' then raw->'roaster_recipe' else null end,
   'verified',s.created_at)
 returning * into new_c;
 cid:=new_c.id;
 insert into private.dic_coffee_first_entry(coffee_id,first_seen_at,first_submission_id,primary_name)
 values(cid,s.created_at,s.id,new_c.name);
 -- No source-kind claim is made from the user's URL alone.
 source_kind:=case when method='official_verified' then 'roaster_page'
                   else 'label' end;
 if nullif(s.source_url,'') is not null then
  insert into public.coffee_sources(coffee_id,source_url,source_kind,field_values,evidence_excerpt,checked_at)
   values(cid,s.source_url,source_kind,
     case when method='official_verified' and jsonb_typeof(evidence->'verified_fields')='object' then evidence->'verified_fields'
          else '{}'::jsonb end,
     left(case when method='official_verified' then
       coalesce(evidence->>'evidence_excerpt','Official roaster product evidence checked.')
     else 'Member-supplied source URL; product page not independently verified.' end,12000),
     now());
 end if;
 update public.coffee_submissions set status='approved',canonical_coffee_id=cid where id=sid;
 update public.library_entries set coffee_id=cid,submission_id=null
 where owner_id=s.owner_id and submission_id=sid;
 if not found then raise exception using errcode='23514',message='Original personal library entry was not preserved.';end if;
 insert into private.dic_coffee_audit(coffee_id,submission_id,actor_id,event_kind,evidence)
 values(cid,sid,auth.uid(),method,coalesce(evidence,'{}'::jsonb));
 return jsonb_build_object('ok',true,'status','verified','coffee_id',cid,'canonical_name',new_c.name,
    'reused',false);
end $function$

CREATE OR REPLACE FUNCTION private.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.account_preferences(owner_id) values(new.id);
  insert into private.beta_members(owner_id) values(new.id);
  insert into private.contributors(owner_id) values(new.id);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.import_operation(expected_owner uuid, doc jsonb, save boolean, review_hash text, recovery_saved boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.require_member(); h text; result jsonb; existing private.import_batches; before_state jsonb; gate boolean;
begin
 if expected_owner is null or expected_owner is distinct from u then raise exception using errcode='42501',message='Account changed; re-open Import Backup.'; end if;
 if doc is null or octet_length(doc::text)>2097152 then raise exception using errcode='22023',message='Choose a backup no larger than 2 MB.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,9311));
 h:=encode(sha256(convert_to(doc::text,'UTF8')),'hex');
 select * into existing from private.import_batches where owner_id=u and source_hash=h;
 if found then return existing.result || jsonb_build_object('alreadyImported',true,'reviewHash',h,'canImport',false); end if;
 select coalesce(saves_enabled and (
      recovery_verified_at is not null OR (
        owner_only_exception_owner_id=u
        and owner_only_exception_approved_at is not null
        and owner_only_exception_expires_at>clock_timestamp()
      )),false) into gate from private.import_control where singleton;
 if save then
  if not coalesce(gate,false) then return jsonb_build_object('ok',false,'code','recovery_required','message','Import is locked until the cloud backup and recovery check is completed. Preview is available now.'); end if;
  if review_hash is distinct from h or recovery_saved is distinct from true then raise exception using errcode='22023',message='Review this exact file and save the recovery copy before importing.'; end if;
  before_state:=private.read_personal_state();
  result:=private.apply_prototype_import(u,doc) || jsonb_build_object('ok',true,'imported',true);
  insert into private.import_batches(owner_id,source_hash,source_document,before_state,result) values(u,h,doc,before_state,result);
  -- One successful owner-only exception commit closes the gate atomically.
  -- Full hosted recovery, when actually verified, uses the original normal gate.
  update private.import_control
     set saves_enabled=false,
         owner_only_exception_owner_id=null,
         owner_only_exception_approved_at=null,
         owner_only_exception_expires_at=null
   where singleton and recovery_verified_at is null
     and owner_only_exception_owner_id=u;
  return result || jsonb_build_object('reviewHash',h);
 end if;
 -- Exceptions are a PostgreSQL subtransaction: no preview records are committed.
 begin
  result:=private.apply_prototype_import(u,doc);
  raise exception using errcode='PZ001',message='preview_rollback';
 exception when sqlstate 'PZ001' then null;
 end;
 return result || jsonb_build_object('ok',true,'imported',false,'alreadyImported',false,'reviewHash',h,'canImport',coalesce(gate,false),
  'blockReason',case when not coalesce(gate,false) then 'Cloud backup and recovery verification is still pending. Preview changes nothing.' else null end);
end $function$

CREATE OR REPLACE FUNCTION private.mutate_workspace(mid uuid, action text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=private.require_member(); h text; prior private.mutation_receipts; result jsonb; pref public.account_preferences;
 sp public.setup_preferences; wc public.workspace_coffees; rp public.recipe_preferences; sh public.shots;
 sid uuid; vid uuid; lid uuid; expected bigint; chosen_style text;
begin
 if action is null or action not in ('select_setup','set_style','save_setup_settings','make_current') then return private.mutate(mid,action,p); end if;
 if mid is null or jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>32000 then raise exception using errcode='22023',message='Invalid mutation payload.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,9311));
 h:=encode(sha256(convert_to(jsonb_build_object('action',action,'payload',p)::text,'UTF8')),'hex');
 select * into prior from private.mutation_receipts where owner_id=u and mutation_id=mid;
 if found then
  if prior.request_hash<>h then raise exception using errcode='22023',message='Mutation ID reused for different changes.'; end if;
  return prior.response;
 end if;
 if action='select_setup' then
  sid:=(p->>'setup_id')::uuid; expected:=private.required_revision(p);
  select * into strict pref from public.account_preferences where owner_id=u for update;
  if pref.revision<>expected then return jsonb_build_object('ok',false,'code','conflict','revision',pref.revision); end if;
  if not exists(select 1 from public.setups where owner_id=u and id=sid and archived_at is null) then raise exception using errcode='42501',message='Setup is not accessible.'; end if;
  update public.account_preferences set active_setup_id=sid where owner_id=u returning * into pref;
  result:=jsonb_build_object('ok',true,'record',to_jsonb(pref));
 elsif action='set_style' then
  sid:=(p->>'setup_id')::uuid;vid:=(p->>'setup_version_id')::uuid;lid:=(p->>'library_entry_id')::uuid;chosen_style:=p->>'style';
  if chosen_style is null or chosen_style not in ('Traditional','Turbo','Fast-Flow','Ristretto','Lungo','Custom') then raise exception using errcode='22023',message='Choose a shot style.'; end if;
  if not exists(select 1 from public.setups where owner_id=u and id=sid and active_version_id=vid) or not exists(select 1 from public.library_entries where owner_id=u and id=lid) then raise exception using errcode='42501',message='Workspace or coffee is not accessible.'; end if;
  if coalesce(p->>'expected_revision','') !~ '^[0-9]+$' then raise exception using errcode='22023',message='Expected revision is required.'; end if;
  select * into wc from public.workspace_coffees where owner_id=u and setup_id=sid and setup_version_id=vid and library_entry_id=lid for update;
  if coalesce(wc.revision,0)<>(p->>'expected_revision')::bigint then return jsonb_build_object('ok',false,'code','conflict','revision',coalesce(wc.revision,0)); end if;
  insert into public.workspace_coffees(owner_id,setup_id,setup_version_id,library_entry_id,selected_style) values(u,sid,vid,lid,chosen_style)
   on conflict(owner_id,setup_id,setup_version_id,library_entry_id) do update set selected_style=excluded.selected_style returning * into wc;
  -- Viewing/changing style does not alter recency or Current Coffee.
  result:=jsonb_build_object('ok',true,'record',to_jsonb(wc));
 elsif action='save_setup_settings' then
  sid:=(p->>'setup_id')::uuid;vid:=(p->>'setup_version_id')::uuid;expected:=private.required_revision(p);
  select * into sp from public.setup_preferences where owner_id=u and setup_id=sid and setup_version_id=vid for update;
  if not found then raise exception using errcode='42501',message='Setup settings not accessible.'; end if;
  if sp.revision<>expected then return jsonb_build_object('ok',false,'code','conflict','revision',sp.revision); end if;
  if jsonb_typeof(p->'track_temperature') is distinct from 'boolean' or jsonb_typeof(p->'track_slow_feed') is distinct from 'boolean' or p->>'temperature_unit' not in ('C','F') or p->>'temperature_unit' is null then raise exception using errcode='22023',message='Provide valid advanced settings.'; end if;
  update public.setup_preferences set track_temperature=(p->>'track_temperature')::boolean,
   slow_feed=case when track_slow_feed is distinct from (p->>'track_slow_feed')::boolean then false else slow_feed end,
   track_slow_feed=(p->>'track_slow_feed')::boolean,temperature_unit=p->>'temperature_unit'
   where owner_id=u and setup_id=sid and setup_version_id=vid returning * into sp;
  result:=jsonb_build_object('ok',true,'record',to_jsonb(sp));
 elsif action='make_current' then
  select * into sh from public.shots where owner_id=u and id=(p->>'shot_id')::uuid;
  if not found or not sh.is_dialed_in or sh.hidden_at is not null or sh.personal_family_id is null then raise exception using errcode='22023',message='Choose your own visible all-green shot.'; end if;
  if not exists(select 1 from public.setups where owner_id=u and id=sh.setup_id and active_version_id=sh.setup_version_id) then raise exception using errcode='22023',message='This is a reference from another equipment version.'; end if;
  select * into rp from public.recipe_preferences where owner_id=u and setup_version_id=sh.setup_version_id and library_entry_id=sh.library_entry_id and style=sh.style for update;
  if coalesce(p->>'expected_revision','') !~ '^[0-9]+$' then raise exception using errcode='22023',message='Expected recipe revision is required.'; end if;
  if coalesce(rp.revision,0)<>(p->>'expected_revision')::bigint then return jsonb_build_object('ok',false,'code','conflict','revision',coalesce(rp.revision,0)); end if;
  insert into public.recipe_preferences(owner_id,setup_id,setup_version_id,library_entry_id,style,current_family_id,favorite_shot_id)
   values(u,sh.setup_id,sh.setup_version_id,sh.library_entry_id,sh.style,sh.personal_family_id,sh.id)
   on conflict(owner_id,setup_id,setup_version_id,library_entry_id,style) do update set current_family_id=excluded.current_family_id,favorite_shot_id=excluded.favorite_shot_id returning * into rp;

  result:=jsonb_build_object('ok',true,'record',to_jsonb(rp));
 end if;
 insert into private.mutation_receipts(owner_id,mutation_id,request_hash,response) values(u,mid,h,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.dic_apply_client_change(expected_owner uuid, mutation_id uuid, action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if action='hide_shot' then
  raise exception using errcode='22023',
   message='This action is no longer available. Your existing shot and offline record are unchanged.';
 end if;
 if expected_owner is null or expected_owner is distinct from auth.uid() then
  raise exception using errcode='42501',message='Account changed before this mutation was submitted. Original pending data was retained.';
 end if;
 if action='rename_setup' then
  return private.rename_setup(mutation_id,payload);
 end if;
 if action='submit_coffee' then
  return private.dic_submit_coffee_auto(mutation_id,payload);
 end if;
 if action='confirm_coffee_existing' then
  return private.dic_confirm_coffee_existing(mutation_id,payload);
 end if;
 if action='save_shot' then
  perform set_config('dic.recommendation_context',
    case when payload ? 'recommendation_context' and
      octet_length((payload->'recommendation_context')::text)<=800
     then (payload->'recommendation_context')::text
     else 'null' end,true);
 end if;
 return private.mutate_workspace(mutation_id,action,payload);
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
